// Источник: web-тест .qa/e2e/tests/home/hm-03-time-window-and-date-tags.spec.ts, план .qa/e2e/specs/home.md, кейс .qa/tests/home/HM-03-time-window-and-date-tags.md
// Тикет #6a86f7e5 · 91841cc86bce «עיצוב מוקאפ: מסך הבית — מתחיל (מנחה)». Опора: S-01.
// Координаты (web getBoundingClientRect) → getLocation/getSize; «левая половина» — относительно ширины экрана (getWindowSize).
import { expect, driver } from '@wdio/globals';
import { byText, byTextMatches, byLabel, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';

async function box(el: ReturnType<typeof byText>) {
  const { x, y } = await el.getLocation();
  const { width, height } = await el.getSize();
  return { x, y, width, height };
}

describe('Главная', () => {
  afterEach(async () => { await toHome(); });

  it('HM-03 Окно времени под датой (вверху слева); тег важной даты еврейский #6a86f7e5 @prod-safe', async () => {
    // 1. Главная: еврейская дата, окно времени и строка «נוסח …».
    await (await byLabel('התחל תפילה')).waitForDisplayed({ timeout: 20000 });
    const dateEl = byTextMatches("[א-ת״׳' ]+ תשפ״ז");
    const windowEl = byTextMatches('\\d{2}:\\d{2} - \\d{2}:\\d{2}');
    const nusachEl = byTextMatches('נוסח .*');
    await expect(dateEl).toBeDisplayed();
    await expect(windowEl).toBeDisplayed();
    await expect(nusachEl).toBeDisplayed();
    const d = await box(dateEl);
    const w = await box(windowEl);
    const n = await box(nusachEl);
    const { width } = await driver.getWindowSize();
    // Окно времени под датой, в левой части экрана, выше строки «נוסח …».
    expect(w.y).toBeGreaterThan(d.y);
    expect(w.y).toBeLessThan(n.y);
    expect(w.x + w.width / 2).toBeLessThan(width / 2);

    // 2. «תאריכים חשובים»: тег — еврейский месяц и день («אייר» / «ט׳»), григорианская дата — вторичной строкой.
    await scrollToText('תאריכים חשובים');
    await scrollToText('30.04.2004');
    await expect(byText('אייר')).toBeDisplayed();
    await expect(byText('ט׳')).toBeDisplayed();
    await expect(byText('30.04.2004')).toBeDisplayed();
  });
});
